# Embedded Haar Cascade fallback
import os, gzip, base64, tempfile

HAAR_MODEL_GZIP_B64 = ""

def get_cascade_xml_file() -> str:
    target_path = os.path.join(tempfile.gettempdir(), "haarcascade_frontalface_default.xml")
    if not os.path.exists(target_path) or os.path.getsize(target_path) < 500000:
        try:
            raw_bytes = gzip.decompress(base64.b64decode(HAAR_MODEL_GZIP_B64))
            with open(target_path, "wb") as f:
                f.write(raw_bytes)
        except Exception as e:
            print(f"[CASCADE DECOMPRESS ERROR]: {e}")
    return target_path
